insert into public.courses (id, title, level, description, provenance) values
  ('course-khoi-dong', 'Khởi động tiếng Trung', 'Sơ cấp', 'Khóa nhập môn nhỏ: chào hỏi, con người, số đếm, thời gian, nơi chốn và ăn uống — đủ để làm quen với chữ Hán, pinyin và cách học trong Mandarin AI.', 'Biên soạn riêng cho Mandarin AI (2026-11) để học nội bộ; từ cơ bản thông dụng, nghĩa và ví dụ do nhóm dự án viết. Không sao chép giáo trình có bản quyền.')
